import React, { useEffect, useState, useContext } from 'react';
import api from '../api/axios';
import CreatePost from '../components/CreatePost';
import PostCard from '../components/PostCard';
import { AuthContext } from '../contexts/AuthContext';

export default function Feed(){
  const [posts,setPosts] = useState([]);
  const { user } = useContext(AuthContext);

  const fetch = async () => {
    try{
      const res = await api.get('/posts?page=1&limit=20');
      setPosts(res.data);
    }catch(err){ console.error(err); }
  };

  useEffect(()=>{ fetch(); }, []);

  const handleNew = (post) => setPosts(prev => [post, ...prev]);
  const updatePost = (id, data) => setPosts(prev => prev.map(p=> p._id===id ? {...p, ...data} : p));

  return (
    <div>
      <h2>Feed</h2>
      {user ? <CreatePost onCreated={handleNew} /> : <p>Login to create posts</p>}
      <div style={{ display:'grid', gap:12, marginTop:12 }}>
        {posts.map(p => <PostCard key={p._id} post={p} currentUser={user} onUpdate={updatePost} />)}
      </div>
    </div>
  );
}
